def skill():
    x = Symbol('x', real=True)
    sols = []
    for sgn in (1, -1):
        xs = solve(Eq((sgn*x) + 4*x + 20, x + 24), x)
        for s in xs:
            if -2 < s < 2 and (s >= 0 if sgn == 1 else s < 0):
                sols.append(s)
    assert len(sols) == 1
    return sols[0] + 10

def standard():
    found = set()
    for num in range(-79, 80):
        x = Rational(num, 40)
        if not (-2 < x < 2):
            continue
        a = lambda n: x + 2*(n - 5)
        if not (a(4)*a(6) < 0):
            continue
        L = sum(abs(a(k + 4)) for k in range(1, 6))
        R = sum(abs(a(2*k)) for k in range(1, 6)) - 2
        if L == R:
            found.add(a(10))
    assert len(found) == 1
    return list(found)[0]

def unique():
    return [standard()]
